"""Class-balanced first-stage loss with strict catalogue holdout."""
from benchmarks.grammar_class_pp_utility_iteration120 import *
from scipy.optimize import minimize
from scipy.special import softmax
OUT=ROOT/'iteration124'

def weighted_objective(w,x,y,weight):
    z=w.reshape(x.shape[1],2);q=softmax(x@z,axis=1);loss=-np.sum(weight*np.log(np.maximum(1e-300,q[np.arange(len(y)),y])))+.0005*(w@w);q[np.arange(len(y)),y]-=1
    return float(loss),(np.asarray(x.T@(q*weight[:,None]))+.001*z).ravel()

def train_balanced(public,train,hidden,lookup,anchors):
    rows={w:cap_rows(masked_type_features(public,hidden,lookup[w])) for w in train};xx=[r['features'] for w in train for r in rows[w]];y=np.array([CLASSES.index(anchors[w]) for w in train for r in rows[w]]);v=ag.vocabulary(xx);x=ag.matrix(xx,v);counts=np.bincount(y,minlength=2);assert min(counts)>0;weight=np.array([1/(2*counts[c]) for c in y]);r=minimize(weighted_objective,np.zeros(x.shape[1]*2),args=(x,y,weight),jac=True,method='L-BFGS-B',options=dict(maxiter=300,ftol=1e-11,gtol=1e-7));assert r.success,r.message
    return dict(vocabulary=v,classes=CLASSES,weights=r.x.reshape(x.shape[1],2).tolist(),loss=float(r.fun),iterations=int(r.nit),n=len(y)),dict(sampled_rows={w:[[r['sid'],r['index']] for r in rr] for w,rr in rows.items()},class_row_counts=counts.tolist(),class_weight_mass=[float(weight[y==c].sum()) for c in range(2)])

def run():
    assert not OUT.exists();OUT.mkdir();(OUT/'proposal-design.md').write_text(Path('docs/grammar_algorithm_proposals.md').read_text())
    paths=[Path(__file__),ROOT/'iteration116/type-split.json',ROOT/'iteration116/training-provenance.json',ROOT/'iteration118/public.json',ROOT/'iteration118/predictions.json',ROOT/'iteration117/models.json',ROOT/'iteration44/annotations-truth.json',ROOT/'iteration49/manifest.json',ROOT/'iteration85/anchor-budgets.json',BASE/'models.json',BASE/'predictions.json',ROOT/'iteration89/models.json',ROOT/'iteration120/cohorts.json',ROOT/'iteration120/settings.json',Path('src/voynich_smt/anchor_grammar.py'),Path('src/voynich_smt/masked_anchor_class.py')]
    save(OUT/'design-freeze.json',dict(inputs={str(p):digest(p) for p in paths},design='Single predeclared class-balanced first-stage change: equal total loss mass per ADP/CCONJ class, same sampled rows/vocabulary/L2/optimizer/3folds as116. Train13 noncatalogue types; all16 target identities/classes masked and excluded from fitting. Recompute OOF13 and balanced scalar offset ONLY13labels. Freeze models before test; exact118 cached source test770/9956; no author selection/newannotations/reserve/sealedlexicaltest. Primary type accuracy/NLL vs frozen118, retain all16; grammatical information is valuable even without lexical nuclei. Fixed class threshold .5; no confidence-gate or PP-threshold tuning. Downstream same120 models/settings/cohorts, unknown andoldpredicted baselines, allresults/grosschanges; primary original.80 precision90% and retain>=188TP plusF1aboveold. PP labels cached85only. This is reuseddevelopment, no independentconfirmation/defaultadoption or Voynich claim.'))
    anchors=load(ROOT/'iteration85/anchor-budgets.json')['195'];split=load(ROOT/'iteration116/type-split.json');train=split['training'];targets=load(ROOT/'iteration93/types.json')['candidates'];assert not set(train)&set(targets);data=load(ROOT/'iteration44/annotations-truth.json');part=load(ROOT/'iteration49/manifest.json')['partitions']['0'];fit=ag.public_sentences([dict(sent_id=i,tokens=[dict(word=t['word']) for t in data[i]['tokens']]) for i in part['fit']],anchors,'fit116');lookup={t['anchor']:t['id'] for s in fit for t in s['tokens'] if t['anchor'] is not None};hidden={lookup[w] for w in targets};models={};provenance={};oof={}
    for fold in range(3):
        held=[w for w in train if split['oof_folds'][w]==fold];tr=[w for w in train if w not in held];hid=hidden|{lookup[w] for w in held};m,prov=train_balanced(fit,tr,hid,lookup,anchors);models[str(fold)]=m;provenance[str(fold)]=dict(train=tr,held=held,**prov);oof.update(grouped_profile(fit,held,lookup,hid,m));print('trained fold',fold,flush=True)
    models['final'],provenance['final']=train_balanced(fit,train,hidden,lookup,anchors);calibrator=fit_offset([oof[w]['mean'] for w in train],[int(anchors[w]=='CCONJ') for w in train],True)
    save(OUT/'models.json',models);save(OUT/'training-provenance.json',provenance);save(OUT/'oof-profiles.json',oof);save(OUT/'calibrator.json',calibrator);save(OUT/'model-freeze.json',dict(inputs={str(OUT/name):digest(OUT/name) for name in ['models.json','training-provenance.json','oof-profiles.json','calibrator.json']}))
    public=load(ROOT/'iteration118/public.json');oldrows=load(ROOT/'iteration118/predictions.json')['full']['rows'];lookup={r['type']:r['opaque'] for r in oldrows};hidden=set(lookup.values());profiles=grouped_profile(public,targets,lookup,hidden,models['final']);rows=[]
    for old in oldrows:
        w=old['type'];p=profiles[w];rows.append(dict(type=w,opaque=lookup[w],n=p['n'],sentences=p['sentences'],probabilities=dict(raw=p['mean'],balanced=float(apply_offset([p['mean']],calibrator)[0]),previous=old['probabilities']['balanced13'],prior=.5)))
    save(OUT/'profiles.json',profiles);save(OUT/'predictions.json',rows);save(OUT/'class-predictions-freeze.json',dict(inputs={str(OUT/'predictions.json'):digest(OUT/'predictions.json'),str(OUT/'profiles.json'):digest(OUT/'profiles.json')}))
    refs=[dict(r,**{'class':anchors[r['type']]}) for r in rows];summary={arm:metrics(refs,arm) for arm in ['raw','balanced','previous','prior']};save(OUT/'class-summary.json',summary);print('CLASS',summary,flush=True)
    tags={r['opaque']:('CCONJ' if r['probabilities']['balanced']>.5 else 'ADP') for r in rows};view=inject(public,hidden,tags);save(OUT/'public.json',view);save(OUT/'assignments.json',tags);save(OUT/'pp-input-freeze.json',dict(inputs={str(OUT/name):digest(OUT/name) for name in ['public.json','assignments.json']}));labels=[dict(sid=r['sid'],index=r['index'],labels=r['labels']) for r in load(BASE/'predictions.json')];scores={name:[r['scores']['pooled_pos']['pp'] for r in infer85(query_rows(view,labels),m)] for name,m in [('original',load(BASE/'models.json')),('augmented',load(ROOT/'iteration89/models.json'))]};save(OUT/'scores.json',scores);save(OUT/'pp-predictions-freeze.json',dict(inputs={str(OUT/'scores.json'):digest(OUT/'scores.json')}));settings=load(ROOT/'iteration120/settings.json');cohorts=load(ROOT/'iteration120/cohorts.json');previous=load(ROOT/'iteration120/scores-predicted.json');unknown=load(ROOT/'iteration120/scores-unknown.json');evaluation={name:{policy:{c:dict(metrics=confusion(labels,scores[name],cut,ii),changes_from_previous=changes(labels,previous[name],scores[name],cut,ii),changes_from_unknown=changes(labels,unknown[name],scores[name],cut,ii)) for c,ii in cohorts.items()} for policy,cut in policies.items()} for name,policies in settings.items()};save(OUT/'evaluation.json',evaluation);print('PP',evaluation['original']['fixed80'],flush=True)
if __name__=='__main__':run()
